function esc(v) { return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function bullets(items) { return `<ul>${items.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>`; }

function article(page, data) {
  const title = esc(page.title);
  const equationCards = data.equations.map((item, index) => `<article class="article-card"><h3>Check ${index + 1}</h3><p>${esc(item)}</p></article>`).join('');
  const designSteps = data.design.map((item, index) => `<li><strong>Review ${index + 1}.</strong> ${esc(item)}</li>`).join('');
  const verification = data.evidence.map((item, index) => `<p><strong>${index + 1}. Evidence item.</strong> Record ${esc(item)}. It should be tied to the specific component and operating case, not copied from a nominal data sheet. This evidence changes the confidence in the final decision.</p>`).join('');
  const decision = data.warning.map((item, index) => `<article class="article-card"><h3>Failure route ${index + 1}</h3><p>${esc(item)}. Treat this as a reason to inspect the underlying load path or duty before changing a part.</p></article>`).join('');
  const relationNotes = data.equations.map((item, index) => `<p><strong>Relationship ${index + 1} in practice.</strong> ${esc(item)}. Before using it, define the section or component to which it applies, the load direction, material-temperature basis and whether the service is steady or cyclic. The relation is a check within the larger component model, not a replacement for the model.</p>`).join('');
  const controlNotes = data.design.map((item, index) => `<p><strong>Control point ${index + 1}.</strong> ${esc(item)}. Assign the responsible discipline and inspection stage, then retain evidence that the as-built or as-installed condition satisfies the stated requirement. This avoids relying on a design intent that was not transferred to manufacture or maintenance.</p>`).join('');
  return `<section id="what"><h2>What is ${title}?</h2><p>${esc(data.overview)}</p><p>${esc(data.mechanism)}</p></section><section id="importance"><h2>Why this topic needs a component-level basis</h2><p>${title} is not reliably assessed by a single catalogue value or by one convenient operating condition. Geometry, material condition, assembly, load path, operating history and failure consequence must be recorded together. The objective is a repeatable engineering decision, not an over-precise calculation based on uncertain inputs.</p><div class="article-callout article-callout--note"><strong>Scope of use.</strong><span>This guidance supports preliminary design, inspection planning and troubleshooting. Final equipment approval must use controlled drawings, applicable standards, manufacturer limits and qualified engineering review.</span></div></section><section id="terms"><h2>Terms used in the assessment</h2><dl class="definition-list"><div><dt>Design case</dt><dd>The combination of geometry, material, load, speed, temperature and support condition used for the check.</dd></div><div><dt>Service condition</dt><dd>The actual operating state, including starts, process upsets, maintenance condition and environmental exposure.</dd></div><div><dt>Acceptance evidence</dt><dd>Measurements, inspection records, calculations and traceable documents supporting a decision.</dd></div></dl></section><section id="principle"><h2>Mechanics and governing relationships</h2><p>${esc(data.mechanism)}</p><div class="article-card-grid">${equationCards}</div><p>Use consistent units and state the source of each property. Where cyclic loading, a weld detail, a keyway, a contact interface or a support flexibility is present, the gross-section result is only the start of the review.</p></section><section id="relationships"><h2>Applying the relationships responsibly</h2>${relationNotes}</section><section id="inputs"><h2>Information required before calculation or selection</h2>${bullets(data.evidence)}<p>Photographs can help confirm an installation, but they do not establish dimensions, material grade, preload, runout, stiffness or load spectrum. Obtain records and measurements that identify the actual component condition.</p></section><section id="method"><h2>Practical design and verification method</h2><ol class="method-list">${designSteps}</ol><p>Recheck the component following manufacture, installation or operating change. Record the measurement position, instrument, temperature, speed or load condition and the acceptance criterion so the next inspection can be compared with a defensible baseline.</p></section><section id="controls"><h2>How design intent becomes a controlled installation</h2>${controlNotes}</section><section id="case"><h2>Example engineering review</h2><p>${esc(data.case)}</p><p>The example illustrates why replacement of a failed component alone is rarely sufficient. The review should identify the initiating mechanism, the feature that concentrated the response, the evidence that confirms it and the design or operating change that prevents recurrence.</p></section><section id="applications"><h2>Where it is used</h2><p>${title} is relevant to ${esc(data.use)}. The same mechanics may apply in other industries, but material properties, environmental exposure, inspection rules and acceptable consequence of failure remain project-specific.</p></section><section id="failure"><h2>Common failure routes and warning signs</h2>${bullets(data.warning)}<div class="article-card-grid">${decision}</div><p>Trend information that is physically connected to the mechanism: torque, temperature, vibration, displacement, strain, leakage, bolt elongation, oil condition or crack indication. A measurement with a known location and operating state is more useful than a single visual judgement.</p></section><section id="maintenance"><h2>Inspection, maintenance and change control</h2><p>Before altering ${title}, confirm isolation, stored energy, lifting, access, hot-work, guarding and process hazards. A modification to material, geometry, coating, lubrication, tightening method, speed, load, support, control logic or operating cycle can change the basis of the original assessment. Update the drawing, maintenance record and test result together.</p></section><section id="verification"><h2>Acceptance and reassessment record</h2>${verification}<h3>Questions for the release review</h3><p>Does the final condition match the documented geometry and material? Has the governing transient or fatigue case been included? Can inspection find the credible initiation location? Are the acceptance values measured under the conditions assumed by the design? If any answer is uncertain, state the limitation and assign the next action rather than declaring the component fully verified.</p></section><section id="faq"><h2>Frequently Asked Questions</h2><div class="faq-list"><details><summary>${esc(data.faq[0])}</summary><p>${esc(data.faq[1])}</p></details><details><summary>What should be checked first?</summary><p>Start with the actual load path, geometry and operating condition, then determine whether the concern is static strength, deformation, fatigue, instability, wear or dynamic response.</p></details><details><summary>Can a handbook formula be used as final approval?</summary><p>No. A handbook relation is useful only when its assumptions, geometry, material properties, loading and safety requirements match the real component and the applicable design standard.</p></details></div></section>`;
}

let updated = 0;
for (const page of candidates.filter((p) => Object.hasOwn(topics, p.id))) {
  const file = path.join(process.cwd(), ...page.route.split('/'), 'index.html');
  let html = fs.readFileSync(file, 'utf8');
  const marker = /<section id="what">[\s\S]*?<section id="related"/;
  if (!marker.test(html)) throw new Error(`No article boundary: ${page.id}`);
  html = html.replace(marker, `${article(page, topics[page.id])}<section id="related"`);
  html = html.replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="${esc(page.title)}: detailed engineering guidance on principles, design inputs, verification, failure modes and safe limits of use.">`);
  html = html.replace(/"dateModified":"[^"]+"/, '"dateModified":"2026-09-01"');
  html = html.replace(/Last reviewed:\s*<time datetime="[^"]+">[^<]+<\/time>/, 'Last reviewed: <time datetime="2026-09-01">1 September 2026</time>');
  fs.writeFileSync(file, html);
  updated += 1;
}
console.log(JSON.stringify({ updated }, null, 2));
